REPLACE INTO `projects` (`id`, `title`, `slug`, `location`, `years`, `end_year`, `working`, `partner`, `description`, `created_at`, `updated_at`) VALUES
	(13, 'Proyek PLTU Suralaya Unit 8', 'proyek-pltu-suralaya-unit-8', 'Suralaya - Banten', '2007', NULL, '<ul><li><p>Cutting and Dispose Soil &amp; Roc</p></li><li><p>Reklamasi (stage 1)</p></li><li><p>Reklamasi (stage 2)</p></li></ul>', 'PT Rekayasa Industri', '<p></p>', '2026-10-12 00:59:11', '2026-10-15 02:19:53'),
	(14, 'Proyek PT Mayora Indah \r\n', 'proyek-pt-mayora-indah', 'Jayanti, Balaraja', '2022', 2024, '<ul><li><p>Urugan tanah</p></li><li><p>Pagar panel beton keliling</p></li><li><p>Drainase</p></li><li><p>Jalan Kawasan</p></li><li><p>Pond &amp; Rumah pompa</p></li><li><p>Concrete Yard</p></li><li><p>Paving block parkir Motor</p></li></ul>', 'Lorem Ipsum Dolor', '<p>Project yang kami laksanakan di tahun 2022 sampai dengan 2024 ini dibagi dalam 3 tahap. Dengan luas areal 38 Ha dan volume urugan tanah merah sebanyak hampir satu juta kubik musuh terbesar adalah hujan selama 3 musim yang kami siasati dengan perbaikan jalan akses dengan material terus menerus dan penggunaan plat baja di area pembuangan. Tahapan selanjutnya berbarengan dengan target pagar keliling sepanjang hampir 5km dan main drainase keliling dengan diameter 2 meter, yang harus diselesaikan dalam kurun waktu 4 bulan. Selanjutnya dilaksanakan 2 Pond berbarengan dengan struktur Bronjong, Turap beton &amp; Rumah Pompa yang mampu menampung buangan air hujan sehingga tidak menjadi masalah untuk pemukiman sekitar.</p><p></p><p>Pada tahap akhir pekerjaan kami melaksanakan Pekerjaan Perkerasan dan Paving block untuk parkir Motor kawasan industri ini seluas hampir 2 Ha dengan Jalan Beton kawasan yang cukup challenging dengan produksi material yang terbatas dan cuaca yang kurang mendukung.</p>', '2026-10-12 00:59:11', '2026-10-15 02:32:53'),
	(15, 'Proyek PT. Tirta Fresindo Jaya', 'proyek-pt-tirta-fresindo-jaya', 'Secang - Magelang', '2026', NULL, '<ul><li><p>Cut &amp; Fill</p></li><li><p>Import tanah Urugan</p></li><li><p>Pagar &amp; Saluran Keliling</p></li></ul>', 'Lorem Ipsum Dolor', '<p>On Progress PT Roda Dunia Abadi dipercaya untuk melaksanakan pekerjaan pematangan tanah di proyek PT. Tirta Fresindo Jaya, Secang – Magelang.</p><p></p><p>Pekerjaan mencakup penyiapan dan pembentukan lahan untuk memastikan kondisi tanah siap mendukung tahapan pembangunan pabrik selanjutnya.</p><p></p><p>Challenge terbesar di project ini adalah ketepatan waktu pengerjaan area prioritas untuk kemudian diserahterimakan secara parsial kepada kontraktor pancang &amp; Sipil.</p>', '2026-10-12 00:59:11', '2026-10-15 02:18:26'),
	(16, 'Proyek PT. Antilope Madju', 'konstruksi-bendungan-pengendali-banjir', 'Putri Indah', '2000', NULL, '<ul><li><p>Lorem Ipsum Dolor</p></li><li><p>Lorem Ipsum Dolor</p></li><li><p>Lorem Ipsum Dolor</p></li></ul>', 'Lorem Ipsum Dolor', '<p></p>', '2026-10-12 00:59:11', '2026-10-12 00:59:11'),
