	(4, 'home', 'about_section', 'About section', 0, '{"about_file": "home/about-files/01M4WQA6DKNAZ64RGR4XGGJ513.pdf", "about_title": "YOUR TRUSTED PARTNER IN SITEWORK", "about_description": "<p>PT. Roda Dunia Abadi mulai didirikan pada tahun 1989. Perusahaan kami bergerak dalam bidang jasa Sipil Site Work dan Infrastruktur. Bidang pekerjaan yang kami kerjakan adalah Pekerjaan Survey Topografi, Land Clearing &amp; Stripping, Galian &amp; Urugan, Pekerjaan Jalan, Saluran Drainase, Pagar Panel Beton keliling, Retaining Wall, Pencegahan Longsoran pada Lereng, Struktur Gabion / Bronjong, Pembuatan &amp; Pengerukkan Pond Treatment, Geotextile &amp; Geomembrane, Dinding Soldier Pile, Pondasi Borpile, Concrete Yard, dan lainnya.<br><br>Sejak berdiri hingga sekarang, kami telah banyak mengerjakan proyek baik proyek berskala nasional seperti PLTU Suralaya sampai ke project Kawasan Industri. Proyek-proyek yang kami kerjakan selama ini telah diselesaikan dengan baik dan dikerjakan secara profesional dengan dukungan Alat Berat dan Armada Dump Truck yang kami miliki serta para Pelaksana lapangan kami yang berpengalaman &amp; Bersertifikat.</p>"}', '2026-10-14 01:08:58', '2026-10-14 23:33:48'),
	(5, 'home', 'services_section', 'Services section', 0, '[{"services_icon": "home/services/01M4WXG3K2CRGK64VEKSEDNABS.png", "services_media": "home/services/01M4WXG3JG1EVBMAD2ERBMAZZ8.png", "services_title": "Site Development", "services_description": "Dari mulai Survey Topografi, Land clearing, Cut & Fill sampai kepada Site grading / Pembentukkan lahan agar siap digunakan untuk kebutuhan konstruksi "}, {"services_icon": "home/services/01M4WXG3KX8P9KKY8VM36XWFJS.png", "services_media": "home/services/01M4WXG3KEQ4DQM7QGZYPRP5VW.png", "services_title": "Infrastructure & Civil Works", "services_description": "Meliputi Pekerjaan Jalan & perkerasan Sub grade, Drainase & Pengendalian air, Pekerjaan Jembatan, Pagar eton keliling, dan lainnya."}, {"services_icon": "home/services/01M4WXG3MYBTRXNJQT9DK3E5GZ.png", "services_media": "home/services/01M4WXG3MFRHYGZ6JR344VX2J4.png", "services_title": "Geotechnical Construction", "services_description": "Meliputi Pekerjaan Pondasi Bored Pile, Soldier Pile & Retaining structure, Dinding penahan tanah (Retaining wall), Landslide mitigation, Slope protect"}]', '2026-10-14 02:57:03', '2026-10-14 23:33:48'),
